        {
          "index": 5,
          "quote": "The default, 200 million transactions"
        }
      ]
    },
    {
      "claim_id": "c8",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 6 says warnings begin at forty million transactions from wraparound; passage 7 says system refuses new XIDs when fewer than three million transactions left. The difference is 40M - 3M = 37M transactions.",
      "citations": [
        {
          "index": 6,
          "quote": "when the database's oldest XIDs reach forty million transactions from the wraparound point"
        },
        {
          "index": 7,
          "quote": "once there are fewer than three million transactions left until wraparound"
        }
      ]
    },
    {
      "claim_id": "c9",
      "verdict": "CONTRADICTED",
      "reasoning": "Passage 8 states that in this condition any transactions already in progress can continue, but only read-only transactions can be started. So new read-only transactions can be started, contradicting 'no new transactions of any kind'.",
      "citations": [
        {
          "index": 8,
          "quote": "only read-only transactions can be started"
        }
      ]
    }
  ]
}

